CREATE TABLE private.marketplace_suppliers(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL CHECK(length(name) BETWEEN 2 AND 100),website text NOT NULL DEFAULT '' CHECK(length(website)<=500),contact_email text NOT NULL DEFAULT '' CHECK(length(contact_email)<=254),fulfillment text NOT NULL CHECK(fulfillment IN ('dropship','wholesale','print_on_demand')),lead_time text NOT NULL DEFAULT '' CHECK(length(lead_time)<=100),notes text NOT NULL DEFAULT '' CHECK(length(notes)<=2000),active boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
REVOKE ALL ON private.marketplace_suppliers FROM public,anon,authenticated;
